/* Cohesive palette: #2d1b2e (dark), #f4e9d8 (light), #e5989b (pink), #6b4e71 (muted purple), #b5838d (rose) */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: #2d1b2e;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
  color: #f4e9d8;
}

.card {
  background-color: #6b4e71;
  border-radius: 24px;
  padding: 24px;
  width: 100%;
  max-width: 400px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

h1 {
  font-size: 1.75rem;
  letter-spacing: 2px;
  color: #f4e9d8;
  text-transform: uppercase;
}

.pet-container {
  width: 160px;
  height: 160px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #b5838d;
  border-radius: 50%;
  border: 4px solid #f4e9d8;
  position: relative;
  overflow: hidden;
}

/* Pixel pet made of CSS blocks */
.pet {
  position: relative;
  width: 100px;
  height: 100px;
}

.ear {
  position: absolute;
  width: 24px;
  height: 24px;
  background-color: #e5989b;
  border: 2px solid #2d1b2e;
  top: -12px;
}

.left-ear {
  left: 8px;
  border-radius: 4px 4px 0 0;
}

.right-ear {
  right: 8px;
  border-radius: 4px 4px 0 0;
}

.face {
  position: absolute;
  width: 80px;
  height: 64px;
  background-color: #e5989b;
  border: 2px solid #2d1b2e;
  border-radius: 8px;
  top: 8px;
  left: 10px;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 8px;
  padding: 8px;
}

.eye {
  width: 16px;
  height: 16px;
  background-color: #2d1b2e;
  border-radius: 50%;
}

.mouth {
  width: 24px;
  height: 8px;
  background-color: #2d1b2e;
  border-radius: 0 0 12px 12px;
  margin-top: 4px;
}

.body {
  position: absolute;
  width: 64px;
  height: 48px;
  background-color: #e5989b;
  border: 2px solid #2d1b2e;
  border-radius: 8px;
  bottom: 0;
  left: 18px;
}

.tail {
  position: absolute;
  width: 16px;
  height: 16px;
  background-color: #e5989b;
  border: 2px solid #2d1b2e;
  border-radius: 50%;
  bottom: 8px;
  right: -8px;
}

.mood {
  font-size: 1.25rem;
  font-weight: bold;
  color: #f4e9d8;
  text-align: center;
  min-height: 1.5em;
}

.stats {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat label {
  font-size: 1rem;
  font-weight: 600;
  color: #f4e9d8;
}

progress {
  width: 100%;
  height: 20px;
  border-radius: 10px;
  border: 2px solid #2d1b2e;
  background-color: #b5838d;
  overflow: hidden;
}

progress::-webkit-progress-bar {
  background-color: #b5838d;
  border-radius: 10px;
}

progress::-webkit-progress-value {
  background-color: #e5989b;
  border-radius: 10px;
  transition: width 0.3s ease;
}

progress::-moz-progress-bar {
  background-color: #e5989b;
  border-radius: 10px;
  transition: width 0.3s ease;
}

.controls {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
  width: 100%;
}

button {
  background-color: #b5838d;
  color: #2d1b2e;
  border: 2px solid #2d1b2e;
  border-radius: 12px;
  padding: 12px 20px;
  font-size: 1rem;
  font-weight: bold;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  flex: 1 1 auto;
  min-width: 80px;
}

button:hover {
  background-color: #e5989b;
}

button:focus-visible {
  outline: 3px solid #f4e9d8;
  outline-offset: 2px;
}

button:active {
  transform: scale(0.96);
  background-color: #6b4e71;
  color: #f4e9d8;
}

@media (max-width: 360px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .pet-container {
    width: 120px;
    height: 120px;
  }
  .pet {
    transform: scale(0.8);
  }
  .controls {
    flex-direction: column;
  }
  button {
    width: 100%;
  }
}

// Pixel Virtual Pet logic
const hungerBar = document.getElementById('hunger-bar');
const happinessBar = document.getElementById('happiness-bar');
const energyBar = document.getElementById('energy-bar');
const moodText = document.getElementById('mood');

const feedBtn = document.getElementById('feed-btn');
const playBtn = document.getElementById('play-btn');
const sleepBtn = document.getElementById('sleep-btn');

// Initial values
let hunger = 70;
let happiness = 70;
let energy = 70;

function updateBars() {
  hungerBar.value = hunger;
  happinessBar.value = happiness;
  energyBar.value = energy;
  updateMood();
}

function updateMood() {
  const avg = (hunger + happiness + energy) / 3;
  if (avg >= 70) {
    moodText.textContent = 'Mood: Happy 😊';
  } else if (avg >= 40) {
    moodText.textContent = 'Mood: Okay 😐';
  } else {
    moodText.textContent = 'Mood: Sad 😢';
  }
}

function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

feedBtn.addEventListener('click', () => {
  hunger = clamp(hunger + 15);
  happiness = clamp(happiness + 5);
  energy = clamp(energy - 5);
  updateBars();
});

playBtn.addEventListener('click', () => {
  hunger = clamp(hunger - 10);
  happiness = clamp(happiness + 20);
  energy = clamp(energy - 15);
  updateBars();
});

sleepBtn.addEventListener('click', () => {
  hunger = clamp(hunger - 5);
  happiness = clamp(happiness + 5);
  energy = clamp(energy + 30);
  updateBars();
});

// Initialize bars and mood
updateBars();
